#!/usr/bin/env python3
"""Round 29 (24 September): every field in the boxes that still picked their
own. Run from ~/Desktop/culprits. Safe to run twice."""
import base64, subprocess, sys, os, tempfile

DIFF = base64.b64decode("")
NOTE = """
## Round 29 (24 September): every field, everywhere

- Boxes written from a source's own template (uMap, ArcGIS apps, My Maps,
  WP Go Maps, Launch Library pads and launches, Trase regions) keep their
  template and now end with a folded "Every field the source gives" list
  (`everyField` in app.js): nested records spelt out with dotted names.
- Country totals list every figure in their record; resource trade flows list
  every field of the flow.
- Worker (`worker/index.js`, CACHE_VERSION v13): live points (EPA TRI, Land
  Matrix, fishing, GFW alerts) carry every upstream field as `x_<name>`, not
  only the picked ones. Needs `cd worker && wrangler deploy`.
- Not done: clicking a Global Forest Watch picture layer (COG or picture
  tiles) still shows nothing; a point read would need GFW's query service.
"""

def git(*a):
    return subprocess.run(["git", *a], capture_output=True, text=True)

if not os.path.exists("map/app.js"):
    sys.exit("Run this from the culprits folder (cd ~/Desktop/culprits).")
with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
    f.write(DIFF); path = f.name
if git("apply", "--check", "-R", path).returncode == 0:
    print("Already applied. Nothing changed.")
else:
    r = git("apply", "--3way", path)
    if r.returncode != 0:
        print(r.stdout + r.stderr)
        git("checkout", "--", "map/app.js", "map/test.mjs", "worker/index.js", "worker/test.mjs")
        sys.exit("Did not apply; nothing changed. Run git pull --no-edit and try again, or send this message back.")
    print("Code changes applied.")
os.unlink(path)
h = open("HANDOFF.md", encoding="utf-8").read()
if "## Round 29 (24 September)" not in h:
    i = h.index("---") + 3
    open("HANDOFF.md", "w", encoding="utf-8").write(h[:i] + "\n" + NOTE + h[i:])
    print("HANDOFF.md note added.")
else:
    print("HANDOFF.md note already there.")
